                reading: SparklineReading::new(points, "34 jobs", "8 jobs", "41 jobs"),
                reason: "The latest sample is unavailable; the verified reading remains.".into(),
            },
        ))
        .into_any_element()
}

fn heatmap(_window: &mut Window, cx: &mut App) -> AnyElement {
    let theme = cx.theme().clone();
    let days = ["Mon", "Tue", "Wed", "Thu", "Fri"];
    let weeks = ["W1", "W2", "W3", "W4"];
    let levels = [
        [Some(0), Some(1), Some(2), None],
        [Some(1), Some(3), Some(2), Some(1)],
        [Some(4), Some(2), Some(0), Some(3)],
        [None, Some(1), Some(4), Some(2)],
        [Some(2), None, Some(1), Some(0)],
    ];
    let mut cells = Vec::new();
    for (row, day) in days.iter().enumerate() {
        for (column, week) in weeks.iter().enumerate() {
            let mut cell =
                HeatCell::new(format!("{day}-{week}"), *day, *week).label(format!("{day} {week}"));
            if let Some(level) = levels[row][column] {
                cell = cell.level(level).value(format!("{level}"));
            }
            cells.push(cell);
        }
    }
    stack(&theme)
        .w(px(420.0))
        .child(caption(
            &theme,
            "five intensity steps; a missing cell is not a measured zero",
        ))
        .child(
            Heatmap::new("scene.heatmap.ready", "Fixture activity")
                .rows(days)
                .columns(weeks)
                .cells(cells),
        )
        .child(Heatmap::new("scene.heatmap.empty", "Fixture activity").state(HeatmapState::Empty))
        .into_any_element()
}

fn code_view(_window: &mut Window, cx: &mut App) -> AnyElement {
    let theme = cx.theme().clone();
    // Spans are the caller's, in byte offsets into each line, and they
    // outrank what the scanner would have found for the same line.
    let lines = [
        CodeLine::new(40, "fn report(&self) -> Outcome {").spans([CodeSpan {
            range: 0..2,
            role: SyntaxColor::Keyword,
        }]),
        CodeLine::new(41, "    let verified = self.check();")
            .spans([CodeSpan {
                range: 4..7,
                role: SyntaxColor::Keyword,
            }])
            .mark(LineMark::Added),
        CodeLine::new(42, "    let stale = self.cached();").mark(LineMark::Removed),
        CodeLine::new(43, "    Outcome::from(verified)").mark(LineMark::Changed),
        CodeLine::new(
            44,
            "    // this line runs off the edge rather than wrapping, because a column carries meaning in code",
        ),
        CodeLine::new(45, "}").mark(LineMark::Error),
    ];
    stack(&theme)
        .w(px(620.0))
        .child(caption(
            &theme,
            "line numbers are the file's, marks are the host's, colour is the caller's",
        ))
        .child(CodeView::new("scene.code.report", lines).language("rust"))
        .child(caption(
            &theme,
            "and where the caller says only what the language is, the four classes it can find",
        ))
        .child(
            CodeView::new(
                "scene.code.scanned",
                [
                    CodeLine::new(1, "def summarize(runs):  # every class in one line"),
                    CodeLine::new(2, "    total = 0"),
                    CodeLine::new(3, "    for run in runs:"),
                    CodeLine::new(4, "        if run.status == \"passed\":"),
                    CodeLine::new(5, "            total += 1"),
                    CodeLine::new(6, "    return total"),
                ],
            )
            .language("python"),
        )
        .child(caption(
            &theme,
            "a language with no table is shown and left plain, never guessed at",
        ))
        .child(
            CodeView::new(
                "scene.code.unknown",
                [
                    CodeLine::new(1, "REPORT SECTION."),
                    CodeLine::new(2, "    MOVE 0 TO TOTAL."),
                ],
            )
            .language("cobol"),
        )
        .into_any_element()
}

fn cascader(window: &mut Window, cx: &mut App) -> AnyElement {
    if !cx.has_global::<SceneCascader>() {
        let cascader = cx.new(|cx| {
            Cascader::new("scene.cascader", window, cx)
                .name("Fixture destination")
                .selected("release-notes")
                .options([
                    CascaderOption::new("guides", "Guides").children([
                        CascaderOption::new("getting-started", "Getting started"),
                        CascaderOption::new("configuration", "Configuration"),
                    ]),
                    CascaderOption::new("reference", "Reference").loading_children(),
                    CascaderOption::new("archive", "Archive").unavailable_children(
                        "The fixture host does not provide archived sections.",
                    ),
                    CascaderOption::new("release-notes", "Release notes"),
                    CascaderOption::new("managed", "Managed section").disabled(true),
                ])
        });
        cascader.update(cx, |cascader, cx| cascader.open(window, cx));
        cx.set_global(SceneCascader { cascader });
    }
    let theme = cx.theme().clone();
    let cascader = cx.global::<SceneCascader>().cascader.clone();
    stack(&theme)
        .w(px(680.0))
        .child(caption(
            &theme,
            "caller-owned hierarchy and value; the open path belongs only to the view",
        ))
        // The trigger is given the width its own popup has, so the scene does
        // not show a control that disagrees with the surface it opens.
        .child(div().w(px(380.0)).child(cascader))
        .into_any_element()
}

